# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor netvlad_residual_cuda(torch::Tensor assignment, torch::Tensor x3d, torch::Tensor clusters2);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("netvlad_residual_cuda", &netvlad_residual_cuda, "Fused NetVLAD residual CUDA");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void netvlad_residual_kernel(
    const float* __restrict__ assignment,
    const float* __restrict__ x3d,
    const float* __restrict__ clusters2,
    float* __restrict__ vlad,
    int B, int N, int K, int D
) {
    int b = blockIdx.x;
    int k = blockIdx.y;
    int d = threadIdx.x;

    if (b >= B || k >= K || d >= D) return;

    float sum_ax = 0.0f;
    float sum_a = 0.0f;

    for (int n = 0; n < N; ++n) {
        float a_val = assignment[b * N * K + n * K + k];
        float x_val = x3d[b * N * D + n * D + d];
        sum_ax += a_val * x_val;
        sum_a += a_val;
    }

    float c2_val = clusters2[d * K + k];
    vlad[b * D * K + d * K + k] = sum_ax - sum_a * c2_val;
}

torch::Tensor netvlad_residual_cuda(torch::Tensor assignment, torch::Tensor x3d, torch::Tensor clusters2) {
    TORCH_CHECK(assignment.is_cuda(), "assignment must be a CUDA tensor");
    TORCH_CHECK(x3d.is_cuda(), "x3d must be a CUDA tensor");
    TORCH_CHECK(clusters2.is_cuda(), "clusters2 must be a CUDA tensor");
    TORCH_CHECK(assignment.is_contiguous(), "assignment must be contiguous");
    TORCH_CHECK(x3d.is_contiguous(), "x3d must be contiguous");
    TORCH_CHECK(clusters2.is_contiguous(), "clusters2 must be contiguous");
    TORCH_CHECK(assignment.dtype() == torch::kFloat32, "assignment must be float32");
    TORCH_CHECK(x3d.dtype() == torch::kFloat32, "x3d must be float32");
    TORCH_CHECK(clusters2.dtype() == torch::kFloat32, "clusters2 must be float32");
    TORCH_CHECK(assignment.dim() == 3, "assignment must be 3D [B,N,K]");
    TORCH_CHECK(x3d.dim() == 3, "x3d must be 3D [B,N,D]");
    TORCH_CHECK(clusters2.dim() == 3, "clusters2 must be 3D [1,D,K]");

    int B = assignment.size(0);
    int N = assignment.size(1);
    int K = assignment.size(2);
    int D = x3d.size(2);

    TORCH_CHECK(x3d.size(0) == B && x3d.size(1) == N, "x3d shape mismatch");
    TORCH_CHECK(clusters2.size(0) == 1 && clusters2.size(1) == D && clusters2.size(2) == K, "clusters2 shape mismatch");

    auto vlad = torch::empty({B, D, K}, assignment.options());

    dim3 grid(B, K);
    dim3 block(D);

    netvlad_residual_kernel<<<grid, block>>>(
        assignment.data_ptr<float>(),
        x3d.data_ptr<float>(),
        clusters2.data_ptr<float>(),
        vlad.data_ptr<float>(),
        B, N, K, D
    );

