        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_9>>>
        assignment = assignment.view(-1, max_sample, self.cluster_size)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_10>>>
        x3d = x.view(-1, max_sample, self.feature_size).contiguous()
