        vlad = vlad - a
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_17>>>
        vlad = F.normalize(vlad)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_18>>>
        vlad = vlad.reshape(-1, self.cluster_size * self.feature_size)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_19>>>
        vlad = F.normalize(vlad)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_20>>>
