        float val = in_bdk[in_idx];
        sum += val * val;
    }
    float norm = sqrtf(sum + EPSILON);
    float inv_norm = 1.0f / norm;

    for (int d = 0; d < D; d++) {
        int in_idx = (b * D + d) * K + k;
        int out_idx = b * (D * K) + d * K + k;
        out_flat[out_idx] = in_bdk[in_idx] * inv_norm;
    }
